/* FL-39 (batch b): 20 functions of GAME.EXE (SHA-256 afd337a2...5c45) at or above 0x480000 ported one to one, in the style of FL-36 (see original_methods_fl36f.h, whose conventions
 * apply unchanged, and the Fl18Host of original_methods_fl18.h): each is its own symbol `m<va>_<name>` that cites the original address in its leading comment, `self` is the
 * original object (ecx) as raw bytes at the original offsets, nothing is bounds checked, and the effects keep the order of the original. The names are descriptive hints, not
 * recovered source names. The constants of every row (field offsets, callees, stored values, sizes) were read from that row's own disassembly by the generator, which also
 * asserted that every row of a kind has the identical masked instruction stream. A dword of `self` that holds an address of the original goes through Fl18Host.resolve;
 * a callee that changes `self` or a global that the function reads again afterwards is not exercised. */

typedef struct Fl39bWorld {
    uint32_t value_5bb57b; /* the dword of the allocation-failure report */
    int16_t word_5c39e3; /* the word of the allocation-failure report (sign-extended) */
    int16_t word_63a4cd; /* the debug word: a non-zero word turns on the trace call */
    uint32_t value_63a58a; /* stored 5 by the reporting path of the row that exits */
} Fl39bWorld;

/* 0x484110, thiscall (ecx is stored in a local and never read), `ret 0xc`, the stack arguments are the original addresses p0, p1, p2 of three dwords: blk = 0x51dc43(0xf07) (cdecl, 1 argument) is stored to dword [p0]. When blk == 0: 0x50ca3e(0x63888b, 0x54da20, dword 0x5bb57b, sign-extended word 0x5c39e3) (cdecl, 4 arguments), 0x42639d(this 0x583979, 0x54da4c, 0x63888b) (thiscall, 2 arguments) and 0x4c97b4(this 0x5cf659); on a null block the original goes on and stores through the null pointer: THIS PORT RETURNS 1 THERE (native rejection, not original behaviour; the oracle maps a zero page so that the rest of the original is executed). Otherwise (returns 0): the 0xf07 bytes at the address in dword [p1] are copied to the address in dword [p0] (rep movsd, movsw, movsb); dword [p2] += 0xf07, then dword [p1] += 0xf07; when the signed word 0x63a4cd is non-zero: 0x44a2b7(0x54da68) (cdecl, 1 argument). */
int32_t m484110_clone_record(uint32_t dst_cell, uint32_t src_cell, uint32_t count_cell, Fl39bWorld *world, const Fl18Host *host);

